import { describe, expect, it } from "vitest";
import { bindingsOf, distinctBindings } from "./bindings.ts";
import { generatorOf, generatedMark, type GeneratedFact } from "./exemptions/generated-file.ts";
import { openEngine } from "./session.ts";

const engine = openEngine({ collectTiming: false });
const MODULE = "ts://@example/app/gen.ts#";

/** The binding records one generated file publishes, read as the run reads it. */
function recordsOf(text: string): readonly string[] {
  const file = engine.parseSourceFile("/project/gen.ts", text);
  const mark = generatedMark(text);
  const generator = generatorOf(file);
  if (mark === undefined) {
    throw new Error("the text is not generated");
  }
  const fact: GeneratedFact = generator === undefined ? mark : { ...mark, generator };
  return distinctBindings(
    bindingsOf(
      new Map([["gen.ts", file]]),
      new Map([["gen.ts", fact]]),
      new Map([["gen.ts", MODULE]]),
    ),
  ).map(
    (one) =>
      `${one.role} ${one.symbol.slice(MODULE.length) || ":file"} ${one.schema ?? one.scope ?? ""} ${one.schema_file}`,
  );
}

const ES_HEADER =
  '// @generated by protoc-gen-es v2.16.0 with parameter "target=ts"\n// @generated from file v1/a.proto (package v1, syntax proto3)\n\n';

const TS_PROTO_HEADER =
  '// Code generated by protoc-gen-ts_proto. DO NOT EDIT.\n// versions:\n//   protoc-gen-ts_proto  v2.15.0\n// source: v1/a.proto\n\nexport const protobufPackage = "v1";\n\n';

describe("the binding identities of a protoc-gen-es v2 file", () => {
  it("binds messages, fields after a bracketed option list, schemas through their type argument, and a service with its RPCs", () => {
    expect(
      recordsOf(
        `${ES_HEADER}/**\n * @generated from message v1.Ping\n */\nexport type Ping = Message<"v1.Ping"> & {\n  /**\n   * @generated from field: string text = 2 [json_name = "words"];\n   */\n  text: string;\n  helper?: number;\n};\n\nexport const PingSchema: GenMessage<Ping> = messageDesc(file, 0);\n\nexport const file: GenFile = fileDesc("");\n\n/**\n * @generated from service v1.Pinger\n */\nexport const Pinger: GenService<{\n  /**\n   * @generated from rpc v1.Pinger.Ping\n   */\n  ping: { methodKind: "unary" },\n}> = serviceDesc(file, 0);\n`,
      ),
    ).toEqual([
      "consumer Ping proto://v1#Ping v1/a.proto",
      "consumer PingSchema proto://v1#Ping v1/a.proto",
      "consumer Ping.text proto://v1#Ping.text v1/a.proto",
      "consumer Pinger proto://v1#Pinger v1/a.proto",
      "consumer Pinger.ping proto://v1#Pinger.Ping v1/a.proto",
    ]);
  });

  it("binds a oneof constituent in the case-constituent form, and an enum with its values", () => {
    expect(
      recordsOf(
        `${ES_HEADER}/**\n * @generated from message v1.Policy\n */\nexport type Policy = Message<"v1.Policy"> & {\n  /**\n   * @generated from oneof v1.Policy.kind\n   */\n  kind: { value: number; case: "keepLast" } | { case: undefined; value?: undefined };\n};\n\n/**\n * @generated from enum v1.Mode\n */\nexport enum Mode {\n  /**\n   * @generated from enum value: MODE_FAST = 0;\n   */\n  FAST = 0,\n}\n`,
      ),
    ).toEqual([
      "consumer Mode proto://v1#Mode v1/a.proto",
      "consumer Mode.FAST proto://v1#Mode.MODE_FAST v1/a.proto",
      "consumer Policy proto://v1#Policy v1/a.proto",
      "consumer Policy.kind.'keepLast':case proto://v1#Policy.keepLast v1/a.proto",
    ]);
  });
});

describe("the binding identities of a ts-proto file", () => {
  it("binds the RPCs of a service path's interface and publishes the file as a fallback of scope types", () => {
    expect(
      recordsOf(
        `${TS_PROTO_HEADER}export interface Ping {\n  text: string;\n}\n\nexport interface Pinger {\n  Ping(request: Ping): Promise<Ping>;\n}\n\nexport const PingerServiceName = "v1.Pinger";\n`,
      ),
    ).toEqual([
      "fallback :file types v1/a.proto",
      "consumer Pinger.Ping proto://v1#Pinger.Ping v1/a.proto",
    ]);
  });

  it("binds a definition's members by their path, and the definition and its client as the service", () => {
    expect(
      recordsOf(
        `${TS_PROTO_HEADER}export const PingerService = {\n  ping: { path: "/v1.Pinger/Ping", requestStream: false },\n} as const;\n\nexport interface PingerClient {\n  ping(request: unknown): Promise<unknown>;\n}\n`,
      ),
    ).toEqual([
      "fallback :file types v1/a.proto",
      "consumer PingerClient proto://v1#Pinger v1/a.proto",
      "consumer PingerService proto://v1#Pinger v1/a.proto",
      "consumer PingerClient.ping proto://v1#Pinger.Ping v1/a.proto",
      "consumer PingerService.ping proto://v1#Pinger.Ping v1/a.proto",
    ]);
  });

  it("publishes a file that writes no service path as one fallback of scope all, and binds nothing in it", () => {
    expect(recordsOf(`${TS_PROTO_HEADER}export interface Ping {\n  text: string;\n}\n`)).toEqual([
      "fallback :file all v1/a.proto",
    ]);
  });
});
